xml.Script:
        Colors[0] := 'EDFF11'; // clYellow
        Colors[1] := 'EE0000'; // clRed
        Colors[2] := '00CC00'; // clGreen
        Colors[3] := '0055EE'; // clBlue
        Colors[4] := 'FFFFFF'; // clWhite

        R := 0.7;

        sAngle := 2 * Pi / 3;
        for i := 0 to 2 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
        end;

        D1 := R / 4 / sqrt(2);
        D2  := R / 2;

        H1 := D1 * 3;
        H2 := D1 * 5;

        az := D1 * 2;

        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle);
        begin
          ca := Cos(Angle);
          sa := Sin(Angle);
          c2 := 1 - Cos(Angle);

          Nx := Xp * (Xv * c2 * Xv + ca) +
                Yp * (Yv * c2 * Xv - sa * Zv) +
                Zp * (Zv * c2 * Xv + sa * Yv);

          Ny := Xp * (Xv * c2 * Yv + sa * Zv) +
                Yp * (Yv * c2 * Yv + ca) +
                Zp * (Zv * c2 * Yv - sa * Xv);

          Nz := Xp * (Xv * c2 * Zv - sa * Yv) +
                Yp * (Yv * c2 * Zv + sa * Xv) +
                Zp * (Zv * c2 * Zv + ca);

          aax[n] := Nx; aay[n] := Ny; aaz[n] := Nz;
          Inc(n);
        end;

        n := 0;
        k := 1/R*sqrt(8)/3;
        for i := 0 to 2 do
            for j := 1 to 5 do begin
                RotatePoint(x[i], y[i],  0,  x[i] * k, y[i] * k, -az * k, sAngle/2 * j);
                RotatePoint(   0,    0, D1,  x[i] * k, y[i] * k, -az * k, sAngle/2 * j);
            end;
